import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CjAa9jTu.js";const d="/unit_devlab_cortex_m_examples/py32f003/placa-superior.png",i="/unit_devlab_cortex_m_examples/py32f003/placa-inferior.png",b=JSON.parse('{"title":"Placa de desarrollo DevLab PY32F003","description":"","frontmatter":{},"headers":[],"relativePath":"py32f003-getting-started/00_about.md","filePath":"py32f003-getting-started/00_about.md"}'),l={name:"py32f003-getting-started/00_about.md"};function n(c,a,s,p,m,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="placa-de-desarrollo-devlab-py32f003" tabindex="-1">Placa de desarrollo DevLab PY32F003 <a class="header-anchor" href="#placa-de-desarrollo-devlab-py32f003" aria-label="Permalink to &quot;Placa de desarrollo DevLab PY32F003&quot;">​</a></h1><h2 id="introduccion" tabindex="-1">Introducción <a class="header-anchor" href="#introduccion" aria-label="Permalink to &quot;Introducción&quot;">​</a></h2><p>La <strong>DevLab PY32F003L24D6TR</strong>, de UNIT Electronics, permite aprender cómo un programa controla entradas, salidas y periféricos de un microcontrolador. En este taller utilizaremos Arduino IDE para escribir C/C++ y un programador CMSIS-DAP para cargar el firmware mediante SWD.</p><p><img src="'+d+'" alt="Vista superior de la placa DevLab PY32F003"></p><h2 id="microcontrolador" tabindex="-1">Microcontrolador <a class="header-anchor" href="#microcontrolador" aria-label="Permalink to &quot;Microcontrolador&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Característica de PY32F003L24D6TR</th><th>Valor</th></tr></thead><tbody><tr><td>Núcleo</td><td>ARM Cortex-M0+ de 32 bits</td></tr><tr><td>Frecuencia máxima de esta variante</td><td>24 MHz</td></tr><tr><td>Memoria Flash</td><td>16 KB (16 384 bytes)</td></tr><tr><td>Memoria SRAM</td><td>2 KB (2 048 bytes)</td></tr><tr><td>Encapsulado</td><td>DFN8 de 3 × 2 mm, con pad de tierra</td></tr><tr><td>ADC</td><td>12 bits</td></tr><tr><td>Interfaces de aplicación</td><td>GPIO, UART, I²C y SPI; con pines compartidos</td></tr><tr><td>Programación y depuración</td><td>SWD</td></tr><tr><td>LED de usuario</td><td>PB5, activo en nivel alto</td></tr><tr><td>Alimentación del taller</td><td>VCC del microcontrolador a 3.3 V</td></tr></tbody></table><p>Los datos de núcleo, memoria y frecuencia corresponden a la columna <strong>PY32F003L24D6</strong> de la tabla 1-4 (página 9) de la <a href="/unit_devlab_cortex_m_examples/py32f003/PY32F003_Datasheet_Rev1.7.pdf">hoja de datos del fabricante, revisión 1.7</a>. En Arduino IDE, esta memoria corresponde a <strong>PY32F003x4</strong>. El sufijo final <code>D6TR</code> no indica que deba elegirse la variante <code>x6</code>.</p><h2 id="componentes-de-la-placa" tabindex="-1">Componentes de la placa <a class="header-anchor" href="#componentes-de-la-placa" aria-label="Permalink to &quot;Componentes de la placa&quot;">​</a></h2><ul><li>Regulador de 5 V a 3.3 V y selector de VCC.</li><li>LED de alimentación y LED de usuario en PB5.</li><li>Botón de reinicio, conectado a la señal compartida PB0/PF2-NRST.</li><li>Cabeceras para alimentación, GPIO y señales de los periféricos.</li><li>Conectores para SWD/I²C y SPI.</li><li>Puente <strong>LED Enable</strong> en la cara inferior: revisa que esté cerrado para usar el LED de usuario.</li></ul><p><img src="'+i+'" alt="Vista inferior con el puente LED Enable"></p><h2 id="alcance-del-taller" tabindex="-1">Alcance del taller <a class="header-anchor" href="#alcance-del-taller" aria-label="Permalink to &quot;Alcance del taller&quot;">​</a></h2><p>Aprenderás a modificar, compilar, programar y comprobar firmware. El PY32F003 no incorpora conectividad Wi-Fi, Bluetooth ni Zigbee; sus interfaces permiten conectar dispositivos externos. Los ejercicios utilizan los recursos locales de la placa y, en las ampliaciones, un adaptador USB-UART y un potenciómetro.</p><p><strong>Siguiente paso:</strong> <a href="./01_setup">Preparar la estación</a>.</p>',13)])])}const h=e(l,[["render",n]]);export{b as __pageData,h as default};
